/**
 * API client.
 *
 * - `createAuthFetch` adds the bearer token, retries ONCE after a silent renew on 401, and turns transport
 *   failures into `NetworkError`.
 * - `createApi` wraps it in a typed `openapi-fetch` client (`paths` from `schema.d.ts`, generated by
 *   `npm run gen:api` from docs/contracts/openapi-app.json) plus `json()` for untyped calls.
 * - `unwrap` turns openapi-fetch's `{data, error, response}` into data-or-throw-`ApiError` for TanStack Query.
 */
import createClient, { type Client } from 'openapi-fetch';

import { getConfig } from '@/config';

import { ApiError, NetworkError, parseProblemResponse, toProblem } from './errors';
import type { paths } from './schema';
import type { QueryParams } from './types';

export interface TokenSource {
  getAccessToken: () => Promise<string | null>;
  /** Silent renew; resolves to the new token or null. */
  renew: () => Promise<string | null>;
  /** Called when a request is still 401 after renewing (session is gone). */
  onUnauthorized?: () => void;
}

export type FetchLike = (input: Request, init?: RequestInit) => Promise<Response>;

function withToken(request: Request, token: string | null): Request {
  if (!token) return request;
  const headers = new Headers(request.headers);
  headers.set('Authorization', `Bearer ${token}`);
  return new Request(request, { headers });
}

export function createAuthFetch(
  tokens: TokenSource,
  baseFetch: typeof fetch = (...a) => globalThis.fetch(...a),
): FetchLike {
  const send = async (req: Request, init?: RequestInit) => {
    try {
      return await baseFetch(req, init);
    } catch (e) {
      if (e instanceof DOMException && e.name === 'AbortError') throw e;
      throw new NetworkError(undefined, { cause: e });
    }
  };

  return async (input, init) => {
    // Keep an unsent copy: a Request body can only be read once.
    const retryCopy = input.clone();
    const token = await tokens.getAccessToken();
    const first = await send(withToken(input, token), init);
    if (first.status !== 401) return first;

    const renewed = await tokens.renew();
    if (!renewed) {
      tokens.onUnauthorized?.();
      return first;
    }
    const second = await send(withToken(retryCopy, renewed), init);
    if (second.status === 401) tokens.onUnauthorized?.();
    return second;
  };
}

export interface Api {
  /** Typed client: `api.client.GET('/api/v1/sites', { params: { query: { limit: 50 } } })`. */
  client: Client<paths>;
  /** Untyped JSON call for endpoints not (yet) in the schema. Throws ApiError / NetworkError. */
  json: <T>(path: string, init?: RequestInit & { query?: QueryParams }) => Promise<T>;
  fetch: FetchLike;
  /** Absolute URL for an API path (CSV downloads and other raw fetches). */
  url: (path: string, query?: QueryParams) => string;
}

export function buildUrl(base: string, path: string, query?: QueryParams): string {
  const url = `${base}${path}`;
  if (!query) return url;
  const qs = new URLSearchParams();
  for (const [k, v] of Object.entries(query)) {
    if (Array.isArray(v)) {
      // Repeated keys (?state=open&state=acknowledged), FastAPI's list query format.
      for (const item of v as readonly (string | number)[]) qs.append(k, String(item));
    } else if (v !== undefined && v !== null && v !== '') {
      qs.set(k, String(v));
    }
  }
  const s = qs.toString();
  return s ? `${url}${url.includes('?') ? '&' : '?'}${s}` : url;
}

function absolute(url: string): string {
  return /^https?:/i.test(url) ? url : new URL(url, window.location.origin).toString();
}

export function createApi(
  tokens: TokenSource,
  options: { baseUrl?: string; baseFetch?: typeof fetch } = {},
): Api {
  const baseUrl = options.baseUrl ?? getConfig().apiBase;
  const authFetch = createAuthFetch(tokens, options.baseFetch);
  const client = createClient<paths>({
    baseUrl: baseUrl || window.location.origin,
    fetch: (req: Request) => authFetch(req),
  });

  const json = async <T>(path: string, init: RequestInit & { query?: QueryParams } = {}) => {
    const { query, ...rest } = init;
    const headers = new Headers(rest.headers);
    headers.set('Accept', 'application/json, application/problem+json');
    if (rest.body !== undefined && !headers.has('Content-Type') && typeof rest.body === 'string') {
      headers.set('Content-Type', 'application/json');
    }
    const res = await authFetch(new Request(absolute(buildUrl(baseUrl, path, query)), { ...rest, headers }));
    if (!res.ok) throw await parseProblemResponse(res);
    if (res.status === 204) return undefined as T;
    const text = await res.text();
    return (text ? JSON.parse(text) : undefined) as T;
  };

  return { client, json, fetch: authFetch, url: (path, query) => absolute(buildUrl(baseUrl, path, query)) };
}

/** openapi-fetch result → data, or throw a typed ApiError built from the problem+json body. */
export async function unwrap<T>(
  result:
    | Promise<{ data?: T; error?: unknown; response: Response }>
    | { data?: T; error?: unknown; response: Response },
): Promise<T> {
  const r = await result;
  if (r.response.ok && r.error === undefined) return r.data as T;
  throw new ApiError(toProblem(r.error, r.response.status, r.response.statusText));
}
